"; $os=Get-CimInstance Win32_OperatingSystem; $cs=Get-CimInstance Win32_ComputerSystem; "OS       : $($os.Caption) build $($os.BuildNumber)"; "Cores    : $($cs.NumberOfLogicalProcessors)  (need 6)"; "RAM      : $([math]::Round($cs.TotalPhysicalMemory/1GB,1)) GB  (need 20+)"; "Free C:  : $([math]::Round((Get-PSDrive C).Free/1GB,1)) GB  (need 100)"; "HyperV OK: $((Get-ComputerInfo).HyperVisorPresent)"; foreach($f in 'VirtualMachinePlatform','Microsoft-Windows-Subsystem-Linux'){ "$f : $((Get-WindowsOptionalFeature -Online -FeatureName $f).State)" }; foreach($p in 443,8088){ $busy = Get-NetTCPConnection -LocalPort $p -State Listen -ErrorAction SilentlyContinue; "Port $p  : $(if($busy){'IN USE'}else{'free'})" }; wsl --version 2>&1 | Select-Object -First 2; foreach($u in 'https://platform-registry.invicti.com/v2/','https://registry-1.docker.io/v2/','https://activation.invicti.com'){ $c=try{(Invoke-WebRequest $u -UseBasicParsing -TimeoutSec 10).StatusCode}catch{$_.Exception.Response.StatusCode.value__}; "$u -> $(if($c){$c}else{'UNREACHABLE'})" };